/bin/bash -lc "python - <<'PY'
import inspect
from pydeseq2.dds import DeseqDataSet
from pydeseq2.ds import DeseqStats
src=inspect.getsource(DeseqDataSet)
for term in ['ref_level','design_factors','design_matrix','_build_design_matrix']:
 print('\\nTERM',term)
 for i,line in enumerate(src.splitlines()):
  if term in line:
   print(i+1, line)
print('\\nDS contrast-related')
src2=inspect.getsource(DeseqStats)
for i,line in enumerate(src2.splitlines()):
 if 'contrast' in line or 'prior_LFC' in line:
  print(i+1,line)
PY"

